CHUNK function:generateChunks (function, generateChunks):
```javascript
function generateChunks(targetY) {
  while (nextGenY < targetY) {
    nextGenY += 80 + rng() * 60; // Gaps between 80 and 140

    let type = Math.floor(rng() * 4);
    let plats = [];

    if (type === 0) {
      // Left side platform
      plats.push({ x: 40, y: nextGenY, w: 100 + rng() * 80, h: 20 });
    } else if (type === 1) {
      // Right side platform
      let w = 100 + rng() * 80;
      plats.push({ x: 360 - w, y: nextGenY, w: w, h: 20 });
    } else if (type === 2) {
      // Two small side platforms
      plats.push({ x: 40, y: nextGenY, w: 80, h: 20 });
      plats.push({ x: 280, y: nextGenY, w: 80, h: 20 });
    } else {
      // Center platform
      plats.push({ x: 120 + rng() * 60, y: nextGenY, w: 100, h: 20 });
    }

    for (let p of plats) {
      platforms.push(p);

      // Spawn entities on platform
      let rand = rng();
      if (rand < 0.25) {
        enemies.push({
          x: p.x + p.w / 2 - 8,
          y: p.y - 16,
          w: 16, h: 16,
          vx: rng() > 0.5 ? 2 : -2,
          type: 'walker',
          plat: p
        });
      } else if (rand < 0.40) {
        enemies.push({
          x: p.x + p.w / 2 - 8,
          y: p.y - 40 - rng() * 30,
          w: 16, h: 16,
          vx: rng() > 0.5 ? 2 : -2,
          type: 'flyer'
        });
      } else if (rand < 0.45) {
        gems.push({
          x: p.x + p.w / 2 - 6,
          y: p.y - 18,
          w: 12, h: 12
        });
      }
    }
  }
}
```

CHUNK function:render (function, render):
```javascript
function render() {
  background(17, 17, 17); // Dark background

  // Render game elements relative to camera
  push();
  translate(0, -cameraY);

  // Platforms
  fill(170, 170, 170);
  for (let p of platforms) {
    rect(p.x, p.y, p.w, p.h);
  }

  // Gems
  fill(34, 255, 34);
  for (let g of gems) {
    rect(g.x, g.y, g.w, g.h);
  }

  // Enemies
  for (let e of enemies) {
    if (e.type === 'flyer') {
      fill(255, 80, 80);
      rect(e.x - 4, e.y + 4, 24, 4);
    } else {
      fill(255, 34, 34);
    }
    rect(e.x, e.y, e.w, e.h);
  }

  // Bullets
  fill(255, 255, 34);
  for (let b of bullets) {
    rect(b.x, b.y, b.w, b.h);
  }

  // Player (flash if invulnerable)
  if (invulnTimer === 0 || Math.floor(frameCount / 4) % 2 === 0) {
    if (!player.lastDir) player.lastDir = 1;
    if (player.vx > 0) player.lastDir = 1;
    if (player.vx < 0) player.lastDir = -1;

    push();
    translate(player.x + player.w / 2, player.y + player.h);
    scale(player.lastDir, 1);

    fill(0, 136, 255);
    stroke(0, 136, 255);
    strokeWeight(2);

    // Head
    noStroke();
    ellipse(0, -12, 8, 8);

    // Body
    stroke(0, 136, 255);
    line(0, -8, 0, -6);

    let isMoving = abs(player.vx) > 0.1;
    let isShooting = player.cooldown > 0 && !player.grounded;

    // Legs
    if (!player.grounded) {
      line(0, -6, -4, -1);
      line(0, -6, 4, -4);
    } else if (isMoving) {
      let cycle = sin(frameCount * 0.5) * 5;
      line(0, -6, -cycle, 0);
      line(0, -6, cycle, 0);
    } else {
      line(0, -6, -2, 0);
      line(0, -6, 2, 0);
    }

    // Arms
    if (isShooting) {
      line(0, -7, 0, -2);
      line(0, -7, 4, -2);
    } else if (isMoving && player.grounded) {
      let cycle = sin(frameCount * 0.5) * 5;
      line(0, -7, cycle, -2);
    } else {
      line(0, -7, 3, -2);
    }
    pop();
  }

  pop();

  // Screen-space UI and Borders
  fill(51, 51, 51);
  rect(0, 0, 40, height);       // Left wall border
  rect(360, 0, 40, height);     // Right wall border

  // HUD: Lives (Top Left, drawn over the left wall)
  fill(255, 34, 34);
  for (let i = 0; i < lives; i++) {
    rect(8, 10 + i * 16, 12, 12);
  }

  // HUD: Ammo (Top Right, drawn over the right wall)
  fill(255, 255, 34);
  for (let i = 0; i < player.ammo; i++) {
    rect(380, 10 + i * 12, 12, 8);
  }
}
```

